import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.BiConsumer;
import java.util.function.BinaryOperator;
import java.util.function.Function;
import java.util.function.Supplier;
import java.util.stream.Collector;

public class Solution {

    public record Sale(String region, String product, int units, BigDecimal unitPrice) {
        public Sale {
            Objects.requireNonNull(region, "region");
            Objects.requireNonNull(product, "product");
            Objects.requireNonNull(unitPrice, "unitPrice");
            if (region.isBlank() || product.isBlank()) {
                throw new IllegalArgumentException("region e product não podem ser vazios");
            }
            if (units <= 0) {
                throw new IllegalArgumentException("units deve ser > 0");
            }
            if (unitPrice.signum() < 0) {
                throw new IllegalArgumentException("unitPrice deve ser >= 0");
            }
        }

        public BigDecimal revenue() {
            return unitPrice.multiply(BigDecimal.valueOf(units))
                    .setScale(2, RoundingMode.HALF_UP);
        }
    }

    public record Report(Map<String, BigDecimal> revenueByRegion,
                         Map<String, Long> unitsByProduct,
                         Optional<Sale> topSale,
                         BigDecimal totalRevenue) {
    }

    public static Collector<Sale, ?, Report> collector() {
        return new ReportCollector();
    }

    public static Report buildReport(List<Sale> sales) {
        Objects.requireNonNull(sales, "sales");
        return sales.stream().collect(collector());
    }

    private static final class Acc {
        private final Map<String, BigDecimal> revenueByRegion = new TreeMap<>();
        private final Map<String, Long> unitsByProduct = new TreeMap<>();
        private BigDecimal total = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP);
        private Sale top;

        void add(Sale sale) {
            revenueByRegion.merge(sale.region(), sale.revenue(), BigDecimal::add);
            unitsByProduct.merge(sale.product(), (long) sale.units(), Long::sum);
            total = total.add(sale.revenue());
            if (top == null || better(sale, top)) {
                top = sale;
            }
        }

        void merge(Acc other) {
            other.revenueByRegion.forEach((region, value) ->
                    revenueByRegion.merge(region, value, BigDecimal::add));
            other.unitsByProduct.forEach((product, units) ->
                    unitsByProduct.merge(product, units, Long::sum));
            total = total.add(other.total);
            if (other.top != null && (top == null || better(other.top, top))) {
                top = other.top;
            }
        }

        Report finish() {
            Map<String, BigDecimal> revenue = Collections.unmodifiableMap(
                    new TreeMap<>(revenueByRegion));
            Map<String, Long> units = Collections.unmodifiableMap(
                    new TreeMap<>(unitsByProduct));
            return new Report(revenue, units, Optional.ofNullable(top),
                    total.setScale(2, RoundingMode.HALF_UP));
        }

        private static boolean better(Sale candidate, Sale current) {
            int byRevenue = candidate.revenue().compareTo(current.revenue());
            if (byRevenue != 0) {
                return byRevenue > 0;
            }
            int byProduct = candidate.product().compareTo(current.product());
            if (byProduct != 0) {
                return byProduct < 0;
            }
            return candidate.region().compareTo(current.region()) < 0;
        }
    }

    private static final class ReportCollector
            implements Collector<Sale, Acc, Report> {

        @Override
        public Supplier<Acc> supplier() {
            return Acc::new;
        }

        @Override
        public BiConsumer<Acc, Sale> accumulator() {
            return Acc::add;
        }

        @Override
        public BinaryOperator<Acc> combiner() {
            return (left, right) -> {
                left.merge(right);
                return left;
            };
        }

        @Override
        public Function<Acc, Report> finisher() {
            return Acc::finish;
        }

        @Override
        public Set<Characteristics> characteristics() {
            return EnumSet.noneOf(Characteristics.class);
        }
    }
}

