import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

class SolutionTest {

    private static Solution.Sale sale(String region, String product, int units, String price) {
        return new Solution.Sale(region, product, units, new BigDecimal(price));
    }

    private static void assertMoney(String expected, BigDecimal actual) {
        assertEquals(0, new BigDecimal(expected).compareTo(actual),
                "esperado " + expected + ", obtido " + actual);
    }

    @Test
    void listaVaziaProduzRelatorioZerado() {
        Solution.Report report = Solution.buildReport(List.of());

        assertEquals(Map.of(), report.revenueByRegion());
        assertEquals(Map.of(), report.unitsByProduct());
        assertEquals(Optional.empty(), report.topSale());
        assertMoney("0.00", report.totalRevenue());
    }

    @Test
    void agregaReceitaPorRegiaoEUnidadesPorProduto() {
        List<Solution.Sale> sales = List.of(
                sale("Sul", "Teclado", 2, "50.00"),
                sale("Sul", "Mouse", 1, "80.00"),
                sale("Norte", "Mouse", 2, "80.00"));

        Solution.Report report = Solution.buildReport(sales);

        assertMoney("180.00", report.revenueByRegion().get("Sul"));
        assertMoney("160.00", report.revenueByRegion().get("Norte"));
        assertEquals(3L, report.unitsByProduct().get("Mouse"));
        assertEquals(2L, report.unitsByProduct().get("Teclado"));
        assertMoney("340.00", report.totalRevenue());
        assertEquals("Mouse", report.topSale().orElseThrow().product());
        assertEquals("Norte", report.topSale().orElseThrow().region());
    }

    @Test
    void desempateDoTopSaleUsaProdutoEDepoisRegiao() {
        List<Solution.Sale> sales = List.of(
                sale("Sul", "B", 1, "10.00"),
                sale("Norte", "A", 2, "5.00"),
                sale("Sul", "A", 1, "10.00"));

        Solution.Report report = Solution.buildReport(sales);

        assertMoney("10.00", report.topSale().orElseThrow().revenue());
        assertEquals("A", report.topSale().orElseThrow().product());
        assertEquals("Norte", report.topSale().orElseThrow().region());
    }

    @Test
    void aplicaArredondamentoComercial() {
        List<Solution.Sale> sales = List.of(sale("Sul", "X", 3, "0.335"));

        Solution.Report report = Solution.buildReport(sales);

        assertMoney("1.01", report.totalRevenue());
    }

    @Test
    void mesmoColetorFuncionaEmParallelStream() {
        List<Solution.Sale> sales = new java.util.ArrayList<>();
        for (int i = 0; i < 10_000; i++) {
            sales.add(sale("R" + (i % 7), "P" + (i % 13), (i % 5) + 1, "1.25"));
        }

        Solution.Report sequential = sales.stream().collect(Solution.collector());
        Solution.Report parallel = sales.parallelStream().collect(Solution.collector());

        assertEquals(sequential.revenueByRegion(), parallel.revenueByRegion());
        assertEquals(sequential.unitsByProduct(), parallel.unitsByProduct());
        assertEquals(sequential.topSale(), parallel.topSale());
        assertMoney(sequential.totalRevenue().toPlainString(), parallel.totalRevenue());
    }

    @Test
    void mapasSaoImutaveisEOrdenados() {
        Solution.Report report = Solution.buildReport(List.of(
                sale("Zona", "Z", 1, "1.00"),
                sale("Alfa", "A", 1, "1.00")));

        assertEquals(List.of("Alfa", "Zona"), List.copyOf(report.revenueByRegion().keySet()));
        assertThrows(UnsupportedOperationException.class,
                () -> report.revenueByRegion().put("X", BigDecimal.ONE));
        assertThrows(UnsupportedOperationException.class,
                () -> report.unitsByProduct().put("X", 1L));
    }

    @Test
    void vendaInvalidaFalhaNaConstrucao() {
        assertThrows(IllegalArgumentException.class,
                () -> sale("Sul", "X", 0, "10.00"));
        assertThrows(IllegalArgumentException.class,
                () -> sale("Sul", "X", 1, "-0.01"));
        assertThrows(IllegalArgumentException.class,
                () -> sale(" ", "X", 1, "10.00"));
        assertThrows(NullPointerException.class,
                () -> sale(null, "X", 1, "10.00"));
    }

    @Test
    void buildReportRejeitaListaNula() {
        assertThrows(NullPointerException.class, () -> Solution.buildReport(null));
    }

    @Test
    void naoAlteraListaDeEntrada() {
        List<Solution.Sale> sales = List.of(sale("Sul", "X", 1, "2.00"));
        Solution.buildReport(sales);
        assertFalse(sales.isEmpty());
        assertEquals(1, sales.size());
    }
}
